function norm(t) { return String(t == null ? "" : t).toUpperCase().replace(/\s+/g, " ").trim(); }
function aco(id) { var q = norm(id), x = null; ACOS.forEach(function (a) { if (norm(a.id) === q) x = a; }); return x; }
function parafuso(classe, d) {
var q = norm(classe), lista = PARAFUSOS.filter(function (p) { return norm(p.id).indexOf(q) === 0 || norm(p.id) === q; });
if (!lista.length) return null;
d = +d || 0;
var ok = lista.filter(function (p) { return d <= p.dmax + 1e-9; });
return ok.length ? ok[0] : lista[lista.length - 1];
}
function chumbador(id) { var q = norm(id), x = null; CHUMBADORES.forEach(function (c) { if (norm(c.id) === q) x = c; }); return x; }
function eletrodo(id) { var q = norm(id), x = null; ELETRODOS.forEach(function (c) { if (norm(c.id) === q) x = c; }); return x; }
function listar(tipo) { return ACOS.filter(function (a) { return !tipo || a.tipo === tipo; }).map(function (a) { return a.id; }); }
